def price_stale(card):
    """Цену на текущем этапе ещё не подтверждали — надо напомнить."""
    etap = S.stage_of(card.get("status"))
    if not etap:
        return False
    return str(etap) not in price_history(card)

def eta_of(card):
    """Сколько дней до Киева и когда. Ручной срок важнее расчётного."""
    manual = card.get("eta_manual")
    if manual:
        try:
            eta = _dt.strptime(str(manual)[:10], "%Y-%m-%d").date()
            return max((eta - _date.today()).days, 0), eta
        except Exception:
            pass
    return S.days_to_kyiv(card)

def apply_value(card_id, field, raw, actor_id):
    """Возвращает (ок, сообщение). Ничего не додумывает."""
    value = (raw or "").strip()
    if not value:
        return False, "Пустое значение не записываю."

    if field == "eta_days":
        digits = "".join(ch for ch in value if ch.isdigit())
        if not digits:
            return False, "Пришлите число дней, например 45."
        n = int(digits)
        if n > 400:
            return False, "Слишком большой срок. Пришлите число дней."
        eta = _date.today() + _td(days=n)
        set_field(card_id, "eta_manual", eta.isoformat(), actor_id)
        set_field(card_id, "days_to_kyiv", n, actor_id)
        return True, "До прибытия %d дней · %s" % (n, eta.strftime("%d.%m.%Y"))

    if field in NUMERIC:
        digits = value.lower().replace(" ", "").replace("\u00a0", "")
        for lishnee in ("цена", "стоимость", "$", "usd", "долларов", "долл"):
            digits = digits.replace(lishnee, "")
        for word, mult in (("тысяч", 1000), ("тыс", 1000), ("к", 1000)):
            if word in digits.lower():
                digits = digits.lower().split(word)[0]
                try:
                    num = int(float(digits.replace(",", ".")) * mult)
                except ValueError:
                    return False, "Не разобрал число. Пришлите цифрами."
                break
        else:
            digits = "".join(ch for ch in digits if ch.isdigit())
            if not digits:
                return False, "Не разобрал число. Пришлите цифрами."
            num = int(digits)
        if field == "engine_cc" and num < 100:
            return False, ("Похоже, это литры. Объём нужен в кубических сантиметрах — "
                           "например, 1598.")
        set_field(card_id, field, num, actor_id)
        return True, "Записано: %s" % S.num(num)

    if field == "vin":
        vin = value.upper().replace(" ", "")
        ok, msg = S.check_vin(vin)
        if not ok:
            return False, "VIN не принят: %s" % msg
        set_field(card_id, field, vin, actor_id)
        return True, "Записано: %s" % vin

    set_field(card_id, field, value, actor_id)
    return True, "Записано."

async def catch_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """CRM-VOICE-FILL-001: voice fills only the explicitly open card."""
    import asyncio
    import time
    import ai
    import ai_fast_schema as fast
    import ai_filter
    import local_ocr

    msg = update.effective_message
    if not msg:
        return
    user_id = update.effective_user.id

    wait = context.user_data.get("car_media_wait")
    if wait:
        target = wait["target"]
        tag = ""
        file_id = None
        if msg.photo:
            file_id = msg.photo[-1].file_id
            if target in ("photos", "condition_photos"):
                unique_id = getattr(msg.photo[-1], "file_unique_id", None) or file_id
                _v166_result = _v165_spool_enqueue(
                    wait["card_id"], target, file_id, user_id, tag,
                    unique_id=unique_id, message_id=msg.message_id)
                _v166_session_ids = wait.setdefault("_fast_session_ids", [])
                state = _v166_result.get("state")
                if state == "accepted" and file_id not in _v166_session_ids:
                    _v166_session_ids.append(file_id)
                elif str(state).startswith("duplicate"):
                    wait["_fast_session_duplicates"] = int(
                        wait.get("_fast_session_duplicates") or 0) + 1
                elif state == "limit":
                    wait["_fast_session_rejected"] = int(
                        wait.get("_fast_session_rejected") or 0) + 1
                _v165_schedule_progress(
                    context, msg, wait["card_id"], target, _v166_session_ids,
                    wait.get("_fast_session_duplicates", 0),
                    wait.get("_fast_session_rejected", 0))
                raise ApplicationHandlerStop
        elif msg.video:
            file_id = msg.video.file_id
            if target in ("videos", "video_h", "video_v"):
                target = "videos"
                slot = _orient(msg.video)
                tag = {"video_h": "гориз", "video_v": "вертик"}.get(slot, "")
        elif msg.video_note:
            file_id = msg.video_note.file_id
        elif msg.document:
            file_id = msg.document.file_id
        card = card_of(wait["card_id"])
        if not card:
            context.user_data.pop("car_media_wait", None)
            return
        if file_id:
            answer = await asyncio.to_thread(save_media, card, target, file_id, user_id, tag)
            if answer:
                await msg.reply_text(answer)
            raise ApplicationHandlerStop
        if msg.text and target == "diag_report":
            pass
        return

    voice_object = msg.voice or msg.audio or msg.video_note
    input_text = (msg.text or "").strip()
    wait = context.user_data.get("car_wait")
    thinking = None
    voice_elapsed = None

    if voice_object:
        active_id = wait.get("card_id") if wait else context.user_data.get("car_voice_active")
        active_card = card_of(active_id) if active_id else None
        if not active_card:
            context.user_data.pop("car_last", None)
            context.user_data.pop("car_voice_active", None)
            await msg.reply_text(
                "Откройте нужную карточку автомобиля и повторите голосовое. "
                "Новая карточка автоматически не создаётся."
            )
            raise ApplicationHandlerStop

        chat_id = getattr(msg, "chat_id", None) or update.effective_chat.id
        marker = "%s:%s" % (chat_id, msg.message_id)
        seen = context.chat_data.get("crm_voice_seen")
        if not isinstance(seen, list):
            seen = []
            context.chat_data["crm_voice_seen"] = seen
        if marker in seen:
            await msg.reply_text("Это голосовое уже обработано.")
            raise ApplicationHandlerStop
        seen.append(marker)
        del seen[:-20]
        context.user_data.pop("voice_undo", None)

        started = time.monotonic()
        hard_deadline = started + 4.65
        thinking = await msg.reply_text("🎤 Распознаю, до 5 секунд...")
        if not ai.voice_enabled():
            if marker in seen:
                seen.remove(marker)
            await thinking.edit_text("Расшифровка голоса не настроена. Карточка не изменена.")
            raise ApplicationHandlerStop
        try:
            import crm_online_guard as _v168_guard
            if not _v168_guard.circuit_allows("stt"):
                if marker in seen:
                    seen.remove(marker)
                await thinking.edit_text(
                    "Сервис распознавания восстанавливается. Карточка не изменена; повторите через 15 секунд.")
                raise ApplicationHandlerStop
        except ApplicationHandlerStop:
            raise
        except Exception:
            pass

        if msg.voice:
            file_id, filename = msg.voice.file_id, "voice.ogg"
        elif msg.audio:
            file_id, filename = msg.audio.file_id, "audio.mp3"
        else:
            file_id, filename = msg.video_note.file_id, "video_note.mp4"

        async def download_voice(fid):
            tg_file = await context.bot.get_file(fid)
            return bytes(await tg_file.download_as_bytearray())

        try:
            remaining = max(0.1, hard_deadline - time.monotonic())
            audio_bytes = await asyncio.wait_for(
                download_voice(file_id), timeout=min(1.1, remaining))
            remaining = max(0.1, hard_deadline - time.monotonic())
            input_text = await asyncio.wait_for(
                asyncio.to_thread(ai.transcribe, audio_bytes, filename),
                timeout=remaining,
            )
            input_text = (input_text or "").strip()
        except asyncio.TimeoutError:
            input_text = ""
            log.warning("CRM voice timeout card=%s", active_id)
        except Exception as e:
            input_text = ""
            log.warning("CRM voice recognition failed card=%s error=%s", active_id, e)
        voice_elapsed = time.monotonic() - started
        try:
            import crm_online_guard as _v168_guard
            _v168_guard.circuit_result("stt", bool(input_text))
            _v168_guard.record_timing(
                "crm_voice", voice_elapsed, "ok" if input_text else "empty",
                card_id=active_id)
        except Exception:
            pass
        if not input_text:
            if marker in seen:
                seen.remove(marker)
