def stage_po_statusu(status):
    s = (status or "").strip().lower()
    if s.startswith("ua_"):
        return "kiev"
    if s.startswith("ge_"):
        return "georgia"
    if s.startswith("sea_"):
        return "sea"
    if s.startswith("kr_"):
        return "korea"
    return ""

def proverit(html, kod=""):
    """КРИТИЧНОЕ — из-за этого публиковать нельзя. Пустой список = можно."""
    bedy = []
    if not html or len(html) < 3000:
        bedy.append("страница пустая или слишком короткая")
        return bedy
    if ("mcf-ch-full" in html) or ("mcf-ch-short" in html):
        bedy.append("в кнопке чата остались служебные теги прежней версии")
    syroy = re.search(r"&lt;(span|div|a)\b[^&]{0,40}class", html)
    if syroy:
        nach = max(0, syroy.start() - 30)
        bedy.append("сырой markup в тексте: …%s…"
                    % html[nach:syroy.end() + 30].replace("\n", " "))
    n = html.count('class="mcf-chat')
    if n != 1:
        bedy.append("виджетов чата на странице: %d (нужен ровно 1)" % n)
    if "Комплексная диагностика" not in html:
        bedy.append("пропал раздел «Комплексная диагностика»")
    if "UA ART" not in html:
        bedy.append("пропала шапка UA ART")
    if kod:
        m = dannye(kod)
        if stage_po_statusu(m.get("status") or m.get("stage")) == "kiev" and SHAG_KIEV_STARYY in html:
            bedy.append("для машины в Киеве осталась старая формулировка этапа")
    return bedy

def zamechaniya(html, kod=""):
    """НЕ критичное: записывается в отчёт, публикацию не отменяет."""
    zam = []
    if kod:
        m = dannye(kod)
        stage = stage_po_statusu(m.get("status") or m.get("stage"))
        if stage and TEKSTY.get(stage) and "mcf-etap" not in html:
            zam.append("нет блока текущего этапа")
        chuzhie = [s for s in TEKSTY if s != stage and ('mcf-%s"' % s) in html]
        if chuzhie:
            zam.append("на странице классы чужих этапов: %s" % ", ".join(chuzhie))
        if "mcf-diag-cta" not in html:
            zam.append("нет кнопки диагностики")

    return zam

def _ua_stage_number(m):
    status = str(m.get("status") or "").strip().lower()
    if status.startswith("kr_"):
        return 1
    if status.startswith("sea_"):
        return 2
    if status == "ge_to_kyiv" or status.startswith("ge_"):
        return 3
    if status.startswith("ua_"):
        return 4
    try:
        saved = int(m.get("stage") or 0)
        if 1 <= saved <= 4:
            return saved
    except Exception:
        pass
    return 1

def _ua_stage_eta(m, stage):
    status = str(m.get("status") or "").strip().lower()
    if stage >= 4 or status.startswith("ua_"):
        return ("arrived", None, None)
    manual = _ua_stage_date(m.get("eta_manual"))
    if manual is not None:
        target = manual
    elif status == "ge_to_kyiv":
        released = _ua_stage_saved_release(m)
        target = released + _ua_stage_dt.timedelta(days=15) if released else None
    elif status.startswith("ge_"):
        target = None
    else:
        shipped = _ua_stage_date(m.get("sea_date_out"))
        target = shipped + _ua_stage_dt.timedelta(days=75) if shipped else None
    if target is None:
        return ("georgia" if status.startswith("ge_") else "unknown", None, None)
    days = max((target - _ua_stage_today()).days, 0)
    return ("due" if days else "soon", days, target)

def _ua_delivery_stage_anchor(m):
    stage = _ua_stage_number(m)
    progress = int(round((stage - 1) * 100.0 / 3.0))
    status = str(m.get("status") or "").strip().lower()
    details = list(_UA_STAGE_DETAILS)
    if status == "ge_to_kyiv":
        details[2] = "Грузия · отправлен в Киев"
    css = r"""<style>
